488		if err != nil || !gotA.Consistent || !gotA.Recomputed.Allowed {
489			t.Fatalf("acme review = %+v, %v", gotA, err)
490		}
491		gotG, err := RecheckDecisionOffline("globex", g, gcp, 2)
492		if err != nil || !gotG.Consistent || gotG.Recomputed.Allowed {
493			t.Fatalf("globex review = %+v, %v", gotG, err)
494		}
495		// One organization's material cannot review another organization.
496		if _, err := RecheckDecisionOffline("acme", g, gcp, 2); !errors.Is(err, ErrInvalidRange) {
497			t.Fatalf("cross-org review err = %v", err)
498		}
499		if _, err := RecheckDecisionOffline("globex", a, acp, 2); !errors.Is(err, ErrInvalidRange) {
500			t.Fatalf("cross-org review err = %v", err)
