		t.Fatal(err)
	}
	if !got2.Consistent || got2.Recomputed.Allowed || got2.Recomputed.Version != 2 ||
		got2.Recomputed.Reason != "no matching allow policy" {
		t.Fatalf("v2 decision review = %+v", got2)
	}
}

